	if bi, ok := debug.ReadBuildInfo(); ok {
		for _, s := range bi.Settings {
			if s.Key == "vcs.revision" && len(s.Value) >= 12 {
				return "forgemark/" + s.Value[:12]
			}
		}
	}
	return "forgemark"
}()

