package bench

import (
	"context"
	"encoding/json"
	"errors"
	"fmt"
	"io"
	"net/http"
	"net/url"
	"os"
	"strings"
	"sync"
	"time"

	githttp "github.com/go-git/go-git/v6/plumbing/transport/http"
	"golang.org/x/sync/singleflight"
)

// credentialProvider supplies the git HTTP basic-auth credential for a push.
// Two implementations cover every forge:
//
//	staticCreds       — a constant username/password (a GitHub/GitLab PAT, a
//	                    Gitea token, or plain basic auth). The common case.
//	jurisdictionCreds — the entiredb identity-token exchange: one short-lived
//	                    jurisdiction token for the whole region, refreshed
//	                    before it expires. Repo-independent, so the repo
//	                    argument is ignored.
type credentialProvider interface {
	basicAuth(ctx context.Context, repo string) (*githttp.BasicAuth, error)
}

// staticCreds returns the same credential for every push. Username is a
// forge-specific placeholder for token auth (github ignores it and treats the
// password as the token; gitlab accepts any username with a PAT).
type staticCreds struct {
	username string
	password string
}

func (s staticCreds) basicAuth(context.Context, string) (*githttp.BasicAuth, error) {
	return &githttp.BasicAuth{Username: s.username, Password: s.password}, nil
}

// jurisdictionCreds exchanges a subject token (a session/SA JWT carrying
// entire:session) for an entiredb jurisdiction token and caches the single
// result, refreshing before expiry. Unlike a per-repo push token, one
// jurisdiction token authorizes every repo the caller can reach — the data
// plane resolves each push live — so there's no per-repo audience and no
// per-repo cache. The exchange is the RFC 8693 shape: audience is the bare
// jurisdiction origin (e.g. https://us.example.com), scope is openid.
type jurisdictionCreds struct {
	httpc    *http.Client
	tokenURL string // core auth /oauth/token, e.g. https://us.auth.example.com/oauth/token
	audience string // jurisdiction host bare origin, e.g. https://us.example.com
	clientID string // public OAuth client, e.g. entire-cli
	subject  string // exchangeable subject JWT (must carry entire:session)
	username string // basic-auth username; Entire ignores it

	ctx    context.Context    // provider-owned; close() cancels it to stop refreshes
	cancel context.CancelFunc // cancels ctx
	wg     sync.WaitGroup     // tracks the detached ahead-of-expiry refresh goroutine

	mu         sync.Mutex
	tok        tokenEntry
	refreshing bool               // a background ahead-of-expiry refresh is in flight
	sf         singleflight.Group // collapses concurrent cold exchanges into one
}

type tokenEntry struct {
	token string
	exp   time.Time
}

// singleflightKey is arbitrary: there is exactly one token, so all callers
// coalesce onto the same key.
const singleflightKey = "jurisdiction"

func newJurisdictionCreds(httpc *http.Client, tokenURL, audience, clientID, subject, username string) *jurisdictionCreds {
	// The exchange must never follow a redirect: the POST body carries the
	// subject token, and Go's default client replays the body on 307/308 — so a
	// redirect served by the (audience-validated) token host could bounce the
	// token to an arbitrary origin, silently bypassing the host pinning. Copy
	// the client (sharing its transport/pool) with redirects refused outright.
	noRedirect := *httpc
	noRedirect.CheckRedirect = func(*http.Request, []*http.Request) error {
		return errors.New("token endpoint attempted a redirect; refusing to forward the subject token")
	}
	ctx, cancel := context.WithCancel(context.Background())
	return &jurisdictionCreds{
		httpc:    &noRedirect,
		tokenURL: tokenURL,
		audience: strings.TrimRight(audience, "/"),
		clientID: clientID,
		subject:  subject,
		username: username,
		ctx:      ctx,
		cancel:   cancel,
	}
}

// close stops the provider: it cancels any in-flight token exchange (including
// a detached ahead-of-expiry refresh) and waits for the refresh goroutine to
// return, so no exchange keeps running — or holding the subject/access token —
// after the run that owns this provider has finished.
func (j *jurisdictionCreds) close() {
	j.cancel()
	j.wg.Wait()
}

func (j *jurisdictionCreds) basicAuth(ctx context.Context, _ string) (*githttp.BasicAuth, error) {
	token, err := j.get(ctx)
	if err != nil {
		return nil, err
	}
	// Entire ignores the username; the token is the password.
	return &githttp.BasicAuth{Username: j.username, Password: token}, nil
}

// get returns a valid jurisdiction token. A still-valid token within 2 minutes
// of expiry is returned immediately while a single background refresh runs
// (serve-stale-while-revalidate): a mid-sweep refresh must not block every
// agent at once, or it injects a synchronized spike into the p99/max tail this
// harness reports. Only a missing/expired token blocks — and singleflight
// collapses those concurrent first-time exchanges (all agents at startup) into
// one /oauth call instead of a herd.
func (j *jurisdictionCreds) get(ctx context.Context) (string, error) {
	if err := ctx.Err(); err != nil {
		return "", fmt.Errorf("jurisdiction token fetch canceled: %w", err)
	}
	j.mu.Lock()
	e := j.tok
	valid := e.token != "" && time.Now().Before(e.exp)
	// Only a valid-but-aging token triggers an ahead-refresh. Guarding on
	// `valid` matters: an expired token also satisfies time.Until < 2m, and
	// setting refreshing=true here without entering the goroutine that clears
	// it would leak the flag and permanently disable ahead-refresh.
	startAhead := valid && time.Until(e.exp) < 2*time.Minute && !j.refreshing
	if startAhead {
		j.refreshing = true
	}
	j.mu.Unlock()

	if valid {
		if startAhead {
			j.wg.Add(1) // so close() can wait for this detached refresh to return
			go func() {
				defer j.wg.Done()
				defer func() {
					j.mu.Lock()
					j.refreshing = false
					j.mu.Unlock()
				}()
				// Best-effort: the cached token is still valid, so a failed
				// ahead-refresh just retries on a later get; surface it but
				// don't disrupt the sweep.
				if _, err := j.refreshNow(); err != nil {
					fmt.Fprintf(os.Stderr, "forgemark: background jurisdiction-token refresh failed: %v\n", err)
				}
			}()
		}
		return e.token, nil
	}
	return j.refreshNow() // no valid token: block on the collapsed exchange
}

// refreshNow exchanges a fresh token and caches it, with singleflight
// collapsing concurrent calls into one network exchange. The exchange runs on
// a detached, time-bounded context so a single caller's cancellation can't
// fail a refresh other agents are waiting on.
func (j *jurisdictionCreds) refreshNow() (string, error) {
	v, err, _ := j.sf.Do(singleflightKey, func() (any, error) {
		// Derive from the provider's context, not context.Background(), so
		// close() cancels an in-flight exchange instead of letting it run its
		// full 30s after the run is over.
		ctx, cancel := context.WithTimeout(j.ctx, 30*time.Second)
		defer cancel()
		e, err := j.exchange(ctx)
		if err != nil {
			return "", err
		}
		j.mu.Lock()
		j.tok = e
		j.mu.Unlock()
		return e.token, nil
	})
	if err != nil {
		return "", fmt.Errorf("jurisdiction token exchange: %w", err)
	}
	token, ok := v.(string)
	if !ok {
		return "", fmt.Errorf("jurisdiction token exchange: unexpected result type %T", v)
	}
	return token, nil
}

func (j *jurisdictionCreds) exchange(ctx context.Context) (tokenEntry, error) {
	form := url.Values{
		"grant_type":           {"urn:ietf:params:oauth:grant-type:token-exchange"},
		"subject_token_type":   {"urn:ietf:params:oauth:token-type:access_token"},
		"requested_token_type": {"urn:ietf:params:oauth:token-type:access_token"},
		"subject_token":        {j.subject},
		"audience":             {j.audience},
		"scope":                {"openid"},
	}
	req, err := http.NewRequestWithContext(ctx, http.MethodPost, j.tokenURL, strings.NewReader(form.Encode()))
	if err != nil {
		return tokenEntry{}, fmt.Errorf("build token request: %w", err)
	}
	req.Header.Set("Content-Type", "application/x-www-form-urlencoded")
	req.SetBasicAuth(j.clientID, "") // public client: empty secret is intentional

	resp, err := j.httpc.Do(req)
	if err != nil {
		return tokenEntry{}, err
	}
	defer func() { _ = resp.Body.Close() }()
	body, err := io.ReadAll(io.LimitReader(resp.Body, 1<<20))
	if err != nil {
		return tokenEntry{}, fmt.Errorf("read token response: %w", err)
	}
	if resp.StatusCode != http.StatusOK {
		// The subject token traveled URL-encoded in the form body, so scrub that
		// rendition too if the endpoint echoes the request back.
		return tokenEntry{}, fmt.Errorf("HTTP %d: %s", resp.StatusCode, redactSecrets(strings.TrimSpace(string(body)), j.subject, url.QueryEscape(j.subject)))
	}
	var jr struct {
		AccessToken string `json:"access_token"`
		ExpiresIn   int    `json:"expires_in"`
	}
	if err := json.Unmarshal(body, &jr); err != nil {
		return tokenEntry{}, fmt.Errorf("decode: %w", err)
	}
	if jr.AccessToken == "" {
		return tokenEntry{}, fmt.Errorf("empty access_token")
	}
	ttl := jr.ExpiresIn
	if ttl <= 0 {
		ttl = 899 // ~15m default matching the jurisdiction-token TTL
	}
	return tokenEntry{token: jr.AccessToken, exp: time.Now().Add(time.Duration(ttl) * time.Second)}, nil
}

package bench

import (
	"context"
	"fmt"
	"io"
	"net/http"
	"strings"

	formatcfg "github.com/go-git/go-git/v6/plumbing/format/config"
)

// endpoint is a fully-resolved push destination: the node base URLs to fan out
// across, the wire object format, and a label for logs/results. It's built once
// at startup by a per-forge constructor. The git remote URL for a (node, repo)
// is always verbatimURLFor — the forges no longer differ on the URL side.
//
// A plain forge has one node (the remote host). Entire discovers its nodes
// from an info/refs probe, because a push must go direct-to-node (its load
// balancer only forwards info/refs, not git-receive-pack).
type endpoint struct {
	nodes  []string
	objFmt formatcfg.ObjectFormat
	label  string
}

// verbatimURLFor joins a node and a caller-supplied repo path with no
// rewriting: the path is used exactly as given in -repos / -repo-pattern, so
// the caller controls the full URL. Surrounding slashes are trimmed so exactly
// one separator is inserted between node and repo.
func verbatimURLFor(node, repo string) string {
	return strings.TrimRight(node, "/") + "/" + strings.Trim(repo, "/")
}

// newGenericEndpoint targets any smart-HTTP git host: one node (the -remote
// base), no discovery, and a URL of <base>/<repo> with the repo path appended
// verbatim (include a .git suffix in -repos if the forge needs it). Object
// format comes from the flag (default sha1 — most forges); pass -object-format
// sha256 for a sha256 remote. github is this with base=https://github.com.
func newGenericEndpoint(base string, objFmt formatcfg.ObjectFormat) *endpoint {
	base = strings.TrimRight(base, "/")
	return &endpoint{
		nodes:  []string{base},
		objFmt: objFmt,
		label:  base,
	}
}

// newEntireEndpoint probes Entire once to learn its nodes (X-Entire-Replicas)
// and object format, then pushes direct-to-node. The probe hits
// info/refs?service=git-receive-pack, which the load balancer does forward,
// using the caller's credential. The repo path is appended verbatim (the caller
// supplies the full path in -repos / -repo-pattern), same as a plain forge.
func newEntireEndpoint(ctx context.Context, remote, objectFmt, repo string, creds credentialProvider, httpc *http.Client) (*endpoint, error) {
	base := strings.TrimRight(remote, "/")

	// Object format: explicit flag wins; otherwise default sha1 (entiredb repos
	// today are sha1) and let the advertisement upgrade it to sha256 if seen.
	objFmt := formatcfg.SHA1
	switch objectFmt {
	case "sha256":
		objFmt = formatcfg.SHA256
	case "sha1", "auto", "":
	default:
		return nil, fmt.Errorf("invalid -object-format %q (sha1|sha256|auto)", objectFmt)
	}

	auth, err := creds.basicAuth(ctx, repo)
	if err != nil {
		return nil, err
	}
	url := verbatimURLFor(base, repo) + "/info/refs?service=git-receive-pack"
	req, err := http.NewRequestWithContext(ctx, http.MethodGet, url, nil)
	if err != nil {
		return nil, fmt.Errorf("build info/refs request: %w", err)
	}
	req.SetBasicAuth(auth.Username, auth.Password)
	resp, err := httpc.Do(req)
	if err != nil {
		return nil, fmt.Errorf("info/refs probe: %w", err)
	}
	defer func() { _ = resp.Body.Close() }()
	body, err := io.ReadAll(io.LimitReader(resp.Body, 1<<20))
	if err != nil {
		return nil, fmt.Errorf("read info/refs response: %w", err)
	}
	if resp.StatusCode != http.StatusOK {
		// A 404 is the most common setup miss, so make it actionable — but
		// diagnose, don't assert: forges also answer 404 for repos the
		// credential simply can't see, so a "create it" order alone would
		// misdirect an auth problem. forgemark deliberately never creates
		// repos (a typo'd path must fail fast, not provision junk on a real
		// jurisdiction); the server body is kept as evidence either way.
		hint := ""
		if resp.StatusCode == http.StatusNotFound {
			hint = fmt.Sprintf(" — repo %s is missing on %s, or the credential can't see it. forgemark does not create repos: "+
				"create it first (`entire repo create` / `entire repo mirror create`) or fix the repo path / token scope", repo, base)
		}
		return nil, fmt.Errorf("info/refs probe: HTTP %d: %s%s", resp.StatusCode,
			redactSecrets(strings.TrimSpace(string(body)), authForms(auth.Username, auth.Password)...), hint)
	}

	if objectFmt == "auto" || objectFmt == "" {
		if strings.Contains(string(body), "object-format=sha256") {
			objFmt = formatcfg.SHA256
		}
	}

	nodes := SplitCSV(resp.Header.Get("X-Entire-Replicas"))
	if len(nodes) == 0 {
		nodes = []string{base} // single-node / dev: talk to the entry host
	}
	return &endpoint{nodes: nodes, objFmt: objFmt, label: base}, nil
}

func SplitCSV(s string) []string {
	var out []string
	for _, p := range strings.Split(s, ",") {
		if p = strings.TrimSpace(p); p != "" {
			out = append(out, p)
		}
	}
	return out
}

